scripts.configuration:
-- Configuration RMAN
CONFIGURE RETENTION POLICY TO RECOVERY WINDOW OF 14 DAYS;
CONFIGURE CONTROLFILE AUTOBACKUP ON;
CONFIGURE CONTROLFILE AUTOBACKUP FORMAT FOR DEVICE TYPE DISK TO '/u01/backup/oracle/%F';
CONFIGURE DEVICE TYPE DISK PARALLELISM 2;
CONFIGURE COMPRESSION ALGORITHM 'MEDIUM';

scripts.full_backup:
-- Sauvegarde complète
RUN {
  ALLOCATE CHANNEL ch1 DEVICE TYPE DISK FORMAT '/u01/backup/oracle/full_%U';
  BACKUP AS COMPRESSED BACKUPSET
    DATABASE
    PLUS ARCHIVELOG DELETE INPUT;
  BACKUP CURRENT CONTROLFILE FORMAT '/u01/backup/oracle/control_%U';
  BACKUP SPFILE FORMAT '/u01/backup/oracle/spfile_%U';
  RELEASE CHANNEL ch1;
}

scripts.incremental_backup:
-- Sauvegarde incrémentale niveau 1
RUN {
  ALLOCATE CHANNEL ch1 DEVICE TYPE DISK FORMAT '/u01/backup/oracle/incr_%U';
  BACKUP AS COMPRESSED BACKUPSET
    INCREMENTAL LEVEL 1
    DATABASE
    PLUS ARCHIVELOG DELETE INPUT;
  RELEASE CHANNEL ch1;
}

scripts.archive_log_backup:
-- Sauvegarde des archive logs
RUN {
  ALLOCATE CHANNEL ch1 DEVICE TYPE DISK FORMAT '/u01/backup/oracle/arch_%U';
  BACKUP AS COMPRESSED BACKUPSET
    ARCHIVELOG ALL DELETE INPUT;
  RELEASE CHANNEL ch1;
}
